def retire_legacy_and_enable_commissions(apps, schema_editor):
    # Existing claims retain their escrow and delivery promises. No cash moves.
    apps.get_model('village', 'VillagePlayerContract').objects.filter(status='OPEN').update(status='LEGACY_CLOSED')
    commands = ['PUBLISH_PERSONAL_COMMISSION', 'INSPECT_PERSONAL_COMMISSIONS',
                'ACCEPT_PERSONAL_COMMISSION', 'ACT_PERSONAL_COMMISSION',
                'WITHDRAW_PERSONAL_COMMISSION', 'ABANDON_PERSONAL_COMMISSION']
    for profile in apps.get_model('village', 'NpcProfile').objects.filter(npc__is_test_only=False, is_active=True):
        profile.capabilities = list(dict.fromkeys([*(profile.capabilities or []), *commands]))
        profile.save(update_fields=['capabilities'])


